import * as React from "react";

import { line } from "@harbor/chart-config";
import { hideChartPopover, showChartPopover } from "../chart-board/board-util";
import { h } from "@stencil/core";
import { createStringFromVNode } from "../../utils/function-helper";
const { getLineSymbols, getCategoricalColors } = line;

// axis tooltip content does not have point color
// so we need to manually inject colors to data
function injectCategoricalColorsAndSymbolToData(data) {
  const symbols = getLineSymbols();
  const colors = getCategoricalColors(data.length);

  const series = data.reduce((total, cur) => {
    if (total.indexOf(cur.serieId) === -1) {
      total.push(cur.serieId);
    }
    return total;
  }, []);

  return data.map((d, i) => ({
    ...d,
    symbol: symbols[series.indexOf(d.serieId) % symbols.length],
    color: d.color || colors[i],
  }));
}

function showLinePointPopover(
  tooltipRef,
  chartRef,
  point,
  event,
  customTooltipFunc?
) {
  const symbols = getLineSymbols();

  const selector = `[xid='${point.x}'][yid='${point.y}']`;

  const type = chartRef.querySelector(selector)?.getAttribute("type");

  const targetSymbol = symbols.find((r) => r.type === type);

  showChartPopover(
    tooltipRef,
    point,
    {
      ...event,
      target: type
        ? selector
        : chartRef.querySelectorAll("circle")[point.index],
    } as MouseEvent,
    customTooltipFunc,
    () => {
      const content = `<div class="--hbr-line-popover-row">
				<div>
					${targetSymbol?.svg(point.color) || ""}
					${point.data.xFormatted}
				</div>
				<div>
					${point.data.yFormatted}
				</div>
			</div>`;
      return content;
    }
  );
}

function toggleLineLegendPopover(legendData, tooltipRef, customTooltipFunc?) {
  const { serieId, data, event, fill } = legendData || {};

  if (!legendData) {
    hideChartPopover(tooltipRef);
  } else {
    const symbols = getLineSymbols();

    // hard wire id may have some issue
    const series = data.reduce((total, cur) => {
      if (total.indexOf(cur.id) === -1) {
        total.push(cur.id);
      }
      return total;
    }, []);

    const targetSymbol = symbols[series.indexOf(serieId) % symbols.length];
    const targetSeies = data.find((r) => r.id === serieId).data;

    showChartPopover(
      tooltipRef,
      { data, event },
      event,
      () =>
        customTooltipFunc?.(
          { ...data, targetSymbol, targetSeies, serieId },
          serieId,
          event
        ),
      () => {
        let res = "";
        targetSeies.forEach((r) => {
          res += `<div class="--hbr-line-popover-row">
					<div>
						${targetSymbol?.svg(fill) || ""}
						${r.x}
					</div>
					<div>
						${r.y}
					</div>
				</div>`;
        });
        return res;
      }
    );
  }
}

/**
 *
 * @param data - either slice data or point data
 * @param chartContextRoot
 * @returns either return a tooltip div for nivo slice to consume
 * @returns or set the content of a existing hbr-popover with no return
 */
function generateOrSetTooltipContentRow(
  data,
  chartContextRoot,
  _showOnlySelectedSerie = false,
  itemTooltip?
) {
  const { slice, point } = data || {};
  const { tooltipRef, chartRef } = chartContextRoot;
  const symbols = getLineSymbols();
  if (slice?.points) {
    if (itemTooltip && typeof itemTooltip === "function") {
      const custom = itemTooltip(slice.points, null, h);

      const ret = React.createElement("div", {
        dangerouslySetInnerHTML: {
          __html:
            typeof custom === "string" ? custom : createStringFromVNode(custom),
        },
      });
      return React.createElement(
        "div",
        {
          className: "--hbr-line-popover-container",
        },
        ret
      );
    }
    const pointElem = slice.points.map((point) => {
      const selector = `[xid='${point.x}'][yid='${point.y}']`;
      const type = chartRef.querySelector(selector).getAttribute("type");

      const targetSymbol = symbols.find((r) => r.type === type);

      return React.createElement(
        "div",
        {
          key: point.id,
          className: "--hbr-line-popover-row",
        },
        React.createElement("div", {
          // biome-ignore lint/security/noDangerouslySetInnerHtml: TODO
          dangerouslySetInnerHTML: {
            __html: `${targetSymbol?.svg(point.color) || ""} ${point.serieId}`,
          },
        }),
        React.createElement("div", {}, point.data.yFormatted)
      );
    });

    return React.createElement(
      "div",
      {
        className: "--hbr-line-popover-container",
      },
      pointElem
    );
  }
  if (point) {
    showLinePointPopover(tooltipRef, chartRef, point, {}, itemTooltip);
  } else {
    hideChartPopover(tooltipRef);
  }
}

const showHorizontalAxisPopover = (
  data,
  event,
  chartContextRoot,
  customTooltipFunc
) => {
  const { tooltipRef } = chartContextRoot;
  const { target } = event;
  const fullData = injectCategoricalColorsAndSymbolToData(data);

  showChartPopover(
    tooltipRef,
    fullData,
    event,
    () => customTooltipFunc?.(fullData, target),
    () =>
      fullData
        .map(
          (d) =>
            `<div class="--hbr-line-popover-row">
  				<div>
  					${d.symbol?.svg(d.color) || ""}
  					${d.serieId}
  				</div>
  				<div>
  					${d.y}
  				</div>
  			</div>`
        )
        .join("")
  );
};

const showVerticalAxisPopover = (
  data,
  event,
  chartContextRoot,
  customTooltipFunc
) => {
  const { tooltipRef } = chartContextRoot;
  const { target } = event;
  const fullData = injectCategoricalColorsAndSymbolToData(data);

  showChartPopover(
    tooltipRef,
    fullData,
    event,
    () => customTooltipFunc?.(fullData, target),
    () => false
  );
};

const hideLinePopover = (tooltipRef) => {
  hideChartPopover(tooltipRef);
};

const convertLineDataToCSV = (arr) => {
  let csv = "group,x,y\n";
  arr.forEach((group) => {
    const groupId = group.id;
    group.data.forEach((item) => {
      const x = item.x || "";
      const y = item.y || "";
      csv += `${groupId},${x},${y}\n`;
    });
  });

  return csv;
};

export {
  generateOrSetTooltipContentRow,
  showHorizontalAxisPopover,
  showVerticalAxisPopover,
  showLinePointPopover,
  toggleLineLegendPopover,
  hideLinePopover,
  convertLineDataToCSV,
};
